<script lang="ts">
  import { t, caption, message as msg, locale } from '../i18n';
  import { liveValue } from './live-value';
  export interface Model {
    page: { paper: string; orient: string; w: number; h: number; W: number; H: number; mt: number; mb: number; ml: number; mr: number; textW: number; font: number; title: boolean; spread: number; numbered: boolean };
    papers: { key: string; name: string }[]; wide: number;
  }
  let { model }: { model: Model } = $props();
  let page = $derived(model.page);
  const round = (value: number) => +(+value).toFixed(2);
  let exportedWith = $derived(t('export.with', 'Exported with {pkg}.', {}, $locale).split('{pkg}'));
</script>
{#snippet number(key: string, value: number)}<input type="number" data-pg={key} {@attach liveValue(round(value))} step="0.1" min="0">{/snippet}
<h3>{t("ui.page.setup", "Page setup", {}, $locale)}</h3><div class="sec">
  <div class="row"><!-- svelte-ignore a11y_label_has_associated_control (Existing compound control caption.) --><label>{t("ui.paper", "Paper", {}, $locale)}</label><div class="ctl"><select data-pg="paper" {@attach liveValue(page.paper)}>{#each model.papers as paper}<option value={paper.key}>{caption(paper.name, $locale)}</option>{/each}</select></div></div>
  <div class="row"><!-- svelte-ignore a11y_label_has_associated_control (Existing compound control caption.) --><label>{t("ui.orientation", "Orientation", {}, $locale)}</label><div class="ctl seg-ctl"><button data-pgo="portrait" class={page.orient !== 'landscape' ? 'on' : ''} title={t("ui.portrait", "Portrait", {}, $locale)}><svg viewBox="0 0 20 20"><path d="M6 3h8v14H6z"/></svg></button><button data-pgo="landscape" class={page.orient === 'landscape' ? 'on' : ''} title={t("ui.landscape", "Landscape", {}, $locale)}><svg viewBox="0 0 20 20"><path d="M3 6h14v8H3z"/></svg></button></div></div>
  <div class="row"><!-- svelte-ignore a11y_label_has_associated_control (Existing compound control caption.) --><label>{t("ui.size.cm", "Size (cm)", {}, $locale)}</label><div class="ctl">{#if page.paper === 'custom'}{@render number('w', page.w)}<span class="x">×</span>{@render number('h', page.h)}{:else}<span class="ro">{round(page.W)} × {round(page.H)}</span>{/if}</div></div></div>
<div class="sec"><div class="sec-title">{t("ui.margins.cm", "Margins (cm)", {}, $locale)}</div><div class="row"><!-- svelte-ignore a11y_label_has_associated_control (Existing compound control caption.) --><label>{t("ui.top.bottom", "Top / bottom", {}, $locale)}</label><div class="ctl">{@render number('mt', page.mt)}{@render number('mb', page.mb)}</div></div><div class="row"><!-- svelte-ignore a11y_label_has_associated_control (Existing compound control caption.) --><label>{t("ui.left.right", "Left / right", {}, $locale)}</label><div class="ctl">{@render number('ml', page.ml)}{@render number('mr', page.mr)}</div></div><div class="row presets">{#each [[msg('page.narrow', 'Narrow'), 1.27], [msg('ui.normal', 'Normal'), 2.5], [msg('page.wide', 'Wide'), 3.5]] as const as [name, value]}<button data-pgm={value} title={t('page.allSides', '{value} cm on all sides', { value }, $locale)}>{caption(name, $locale)}</button>{/each}</div><div class="hint-line">{t("page.textWidth", "Text width {w} cm", { w: round(page.textW) }, $locale)}{#if model.wide} · <b>{model.wide > 1 ? t("page.wideMany", "{n} diagrams are wider and will be scaled down", { n: model.wide }, $locale) : t("page.wideOne", "1 diagram is wider and will be scaled down", {}, $locale)}</b>{/if}</div></div>
<div class="sec"><div class="sec-title">{t("ui.text", "Text", {}, $locale)}</div>
  <div class="row"><!-- svelte-ignore a11y_label_has_associated_control (Existing compound control caption.) --><label>{t("ui.font.size", "Font size", {}, $locale)}</label><div class="ctl"><select data-pg="font" {@attach liveValue(String(+page.font))}>{#each [10, 11, 12] as value}<option value={String(value)}>{t("page.fontPt", "{n} pt", { n: value }, $locale)}</option>{/each}</select></div></div>
  <div class="row"><!-- svelte-ignore a11y_label_has_associated_control (Existing compound control caption.) --><label>{t("ui.title", "Title", {}, $locale)}</label><div class="ctl"><label class="chk"><input type="checkbox" data-pg="title" checked={page.title}>{t("ui.show.document.name.as.title.variant1", " Show document name as title", {}, $locale)}</label></div></div>
  <div class="row"><!-- svelte-ignore a11y_label_has_associated_control (Existing compound control caption.) --><label>{t("ui.line.spacing", "Line spacing", {}, $locale)}</label><div class="ctl"><select data-pg="spread" {@attach liveValue(String(+page.spread || 1))}>{#each [[1, msg('page.single', 'Single')], [1.15, '1.15'], [1.3, msg('page.oneHalf', 'One and a half')], [1.6, msg('page.double', 'Double')]] as const as [value, name]}<option value={String(value)}>{caption(name, $locale)}</option>{/each}</select></div></div>
  <div class="row"><!-- svelte-ignore a11y_label_has_associated_control (Existing compound control caption.) --><label>{t("ui.sections", "Sections", {}, $locale)}</label><div class="ctl"><label class="chk"><input type="checkbox" data-pg="numbered" checked={page.numbered}>{t("ui.number.headings.1.1.1.1.1.1.variant1", " Number headings (1, 1.1, 1.1.1)", {}, $locale)}</label></div></div></div>
<div class="sec"><div class="help">{exportedWith[0]}<code>\usepackage&#123;geometry&#125;</code>{exportedWith[1]} {t("page.printSameSize", "Print uses the same page size.", {}, $locale)}</div></div>
